<?php
use App\Controllers\LiveController;
use App\Core\Session;
use App\Services\Workspace;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->order($_GET['order'] ?? null));
if (isset($live['error']) || isset($live['error_code'])): ?>
<?= U::heading('Order not found', $live['error'] ?? 'Choose an order from your order history.') ?><?= U::btn('My orders', '/customer/orders', 'primary', 'arrow-left') ?>
<?php return; endif;
$o = $live['order']; $station = $live['station']; $pickup = $o['fulfillment'] === 'pickup';
$steps = $pickup ? ['confirmed', 'preparing', 'ready', 'collected', 'completed'] : ['confirmed', 'preparing', 'ready', 'out_for_delivery', 'delivered', 'completed'];
$reached = array_column($live['timeline'], 'at', 'to');
$current = array_search($o['status'], $steps, true);
$fee = $o['final_fee_centavos'] ?? $o['quoted_fee_centavos'];
$token = U::e(Session::csrfToken());
$hidden = static fn (): string => '<input type="hidden" name="_token" value="' . $token . '"><input type="hidden" name="order_id" value="' . U::e($o['id']) . '"><input type="hidden" name="expected_version" value="' . (int) $o['version'] . '"><input type="hidden" name="request_key" value="' . U::e(LiveController::key()) . '">';
?>
<div data-poll-url="/customer/tracking/status?order=<?= U::e($o['id']) ?>" data-poll-version="<?= (int) $o['version'] ?>" data-poll-seconds="30" hidden></div>
<?= U::heading('Order ' . ($o['order_no'] ?? ''), $station['name'] . ' · placed ' . S::time($o['created_at']), U::btn('Message station', '/customer/messages?station=' . $station['id'], 'primary', 'message') . U::btn('My orders', '/customer/orders', 'secondary', 'arrow-left')) ?>
<?php if ($o['status'] === 'on_hold' && !empty($live['duplicate_of'])): $d = $live['duplicate_of']; ?>
<section class="mb-5 rounded-xl border border-amber-200 bg-amber-50 p-5" role="alert"><h2 class="font-bold text-amber-900">Is this a repeat order?</h2><p class="mt-1 text-sm text-amber-900">It matches order <a class="font-semibold underline" href="/customer/tracking?order=<?= U::e($d['id']) ?>"><?= U::e($d['order_no']) ?></a> (<?= U::e(S::label($d['status'], $o['fulfillment'])) ?>, <?= S::pesos($d['total_centavos']) ?>), placed <?= U::e(S::time($d['created_at'])) ?>. The station will not prepare this one until you decide.</p>
<div class="mt-4 flex flex-wrap gap-2"><form method="post" action="/customer/orders/confirm" data-submit-once><?= $hidden() ?><?= U::btn('Yes, I want another', '', 'primary', 'check', ['type' => 'submit']) ?></form><form method="post" action="/customer/orders/cancel" data-submit-once><?= $hidden() ?><input type="hidden" name="reason" value="Duplicate order declined by customer"><?= U::btn('Cancel this one', '', 'secondary', 'close', ['type' => 'submit']) ?></form></div></section>
<?php endif ?>
<div class="grid gap-5 lg:grid-cols-2"><div class="space-y-5">
<section class="panel p-5 md:p-6"><div class="flex flex-wrap items-center justify-between gap-3"><?= U::title('Order progress', 'orders', '') ?><?= S::badge($o['status'], $o['fulfillment']) ?></div>
<?php if ($o['status'] === 'scheduled'): ?><p class="mt-3 rounded-lg bg-foam p-3 text-sm">Scheduled for <strong><?= U::e(S::time($o['requested_at'])) ?></strong>. The station starts it on that day.</p><?php endif ?>
<?php if ($o['status'] === 'cancelled'): ?><p class="mt-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-800">Cancelled<?= $o['cancel_reason'] ? ': ' . U::e($o['cancel_reason']) : '' ?>.</p><?php endif ?>
<ol class="mt-5"><?php foreach ($steps as $i => $step): $done = isset($reached[$step]) || ($current !== false && $i < $current); $now = $step === $o['status']; ?>
<li class="relative flex gap-4 pb-6 last:pb-0"><div class="relative flex flex-col items-center"><span class="relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full <?= $done || $now ? 'bg-water text-white' : 'border-2 border-line bg-white' ?>"><?= $done ? U::icon('check', 'size-4') : '' ?></span><?php if ($i < count($steps) - 1): ?><span class="absolute bottom-0 top-8 w-0.5 <?= $done ? 'bg-water' : 'bg-line' ?>"></span><?php endif ?></div><div class="flex flex-1 flex-wrap justify-between gap-2"><h3 class="font-bold <?= $done || $now ? '' : 'text-muted' ?>"><?= U::e(S::label($step, $o['fulfillment'])) ?></h3><time class="text-sm text-muted"><?= U::e(isset($reached[$step]) ? S::time($reached[$step], 'g:i A') : '') ?></time></div></li>
<?php endforeach ?></ol><p class="mt-4 text-xs text-muted">This page checks for updates every 30 seconds.</p></section>
<section class="panel p-5 md:p-6"><?= U::title('Items', 'bottle', 'mb-4') ?><?= U::table(['Item', 'Qty', 'Price', 'Total'], array_map(static fn (array $i): array => [U::e($i['name']) . ($i['pack_text'] ? '<span class="block text-xs text-muted">' . U::e($i['pack_text']) . '</span>' : ''), (int) $i['quantity'], S::pesos($i['unit_price_centavos']), S::pesos($i['line_total_centavos'])], $live['items']), ['data-no-search' => true]) ?>
<dl class="mt-4 space-y-2 text-sm"><div class="flex justify-between"><dt class="text-muted">Items</dt><dd><?= S::pesos($o['subtotal_centavos']) ?></dd></div><?php if (!$pickup): ?><div class="flex justify-between"><dt class="text-muted">Delivery fee<?= $o['distance_display'] !== null ? ' (' . U::e($o['distance_display']) . ' km)' : '' ?></dt><dd><?= S::pesos($fee) ?><?= $o['final_fee_centavos'] !== null && $o['final_fee_centavos'] < $o['quoted_fee_centavos'] ? ' <span class="text-xs text-emerald-700">lowered from ' . S::pesos($o['quoted_fee_centavos']) . '</span>' : '' ?></dd></div><?php endif ?></dl>
<div class="mt-4 flex justify-between font-bold"><span>Total</span><span><?= S::pesos($o['total_centavos']) ?></span></div><p class="mt-4 rounded-lg bg-foam p-3 text-sm"><span class="text-muted">Payment:</span> <strong><?= $pickup ? 'Cash on pickup' : 'Cash on delivery' ?></strong></p></section></div>
<div class="space-y-5"><section class="panel p-5 md:p-6"><?php if ($pickup): ?><?= U::title('Pickup information', 'store', 'mb-4') ?><p class="font-bold"><?= U::e($station['name']) ?></p><p><?= U::e($station['address']) ?></p><?php if ($station['phone']): ?><p class="mt-2 text-sm"><a class="font-semibold text-water" href="tel:<?= U::e($station['phone']) ?>"><?= U::e($station['phone']) ?></a></p><?php endif ?><p class="mt-3 text-sm text-muted">Bring your empty containers and pay at the station. Go when this page says “Ready for pickup”.</p>
<?php else: ?><?= U::title('Delivery information', 'truck', 'mb-4') ?><?php if (!empty($live['driver'])): ?><div class="mb-4 flex items-center gap-3"><?= U::avatar(mb_strtoupper(mb_substr($live['driver']['name'], 0, 1))) ?><div class="flex-1"><p class="font-bold">Rider <?= U::e($live['driver']['name']) ?></p><p class="text-sm text-muted">Delivering your order</p></div><?= U::btn('Call', 'tel:' . $live['driver']['phone'], 'secondary', 'phone') ?></div><?php endif ?><p class="font-semibold"><?= U::e($o['address_label'] ?? '') ?></p><p class="text-muted"><?= U::e($o['address_text'] ?? '') ?></p><?php if (!empty($o['address_landmark'])): ?><p class="text-sm text-muted">Landmark: <?= U::e($o['address_landmark']) ?></p><?php endif ?><?php endif ?>
<?php if ($o['note'] !== ''): ?><p class="mt-3 rounded-lg bg-foam p-3 text-sm"><span class="text-muted">Your note:</span> <?= U::e($o['note']) ?></p><?php endif ?></section>
<?php if (!empty($live['can_reschedule'])): ?><section class="panel p-5 md:p-6"><?= U::title('Change the time', 'calendar', 'mb-3') ?><form method="post" action="/customer/orders/reschedule" class="flex flex-wrap items-end gap-3" data-submit-once><?= $hidden() ?><?= U::field('New date and time', 'requested_at', '', 'datetime-local', ['required' => true]) ?><?= U::btn('Reschedule', '', 'secondary', 'calendar', ['type' => 'submit']) ?></form></section><?php endif ?>
<?php if (!empty($live['can_cancel']) && $o['status'] !== 'on_hold'): ?><section class="rounded-xl border border-rose-200 bg-rose-50 p-5"><h2 class="font-bold text-rose-900">Cancel this order</h2><p class="mt-1 text-sm text-rose-800">You can cancel until the station starts preparing it.</p><form method="post" action="/customer/orders/cancel" class="mt-3 space-y-3" data-submit-once><?= $hidden() ?><?= U::field('Reason', 'reason', '', 'text', ['required' => true, 'maxlength' => '500', 'placeholder' => 'I no longer need it']) ?><?= U::btn('Cancel order', '', 'secondary', 'close', ['type' => 'submit', 'data-confirm' => 'Cancel this order? This cannot be undone.']) ?></form></section>
<?php elseif (!in_array($o['status'], ['cancelled', 'completed', 'delivered', 'collected', 'on_hold'], true)): ?><section class="rounded-xl border border-line bg-foam p-5 text-sm"><h2 class="font-bold">Need to change something?</h2><p class="mt-1 text-muted">The station has started this order, so it can no longer be cancelled here. Message the station for help.</p></section><?php endif ?>
<section class="panel p-5 md:p-6"><?= U::title('Order history', 'clock', 'mb-4') ?><?= U::table(['When', 'Status', 'Note'], array_map(static fn (array $l): array => [U::e(S::time($l['at'])), U::e(S::label($l['to'], $o['fulfillment'])), U::e($l['reason'] ?? '')], $live['timeline']), ['data-no-search' => true]) ?></section></div></div>
